const s = await jira.listStories();
const f = (x:any)=> x.gone? {id:x.id,gone:x.reason}:{id:x.id,t:x.issueType,sum:x.summary,st:x.status.name,cat:x.status.category,pts:x.points,asg:x.assignee?.name??null,epic:x.epic,labels:x.labels,lastC:x.comments.slice(-2).map((c:any)=>`${c.at.slice(0,10)} ${c.author}: ${c.body.slice(0,200)}`)};
return {epic: e.gone?e:{...f(e),desc:e.description.slice(0,600)}, stories:s.map(f)};

